    runs: list[Run], played: Played, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    spec = runs[0].record.spec
    two_teams = replace(
        spec,
        world="snake",
        teams=(
            TeamSpec("prey", (0,), "time alive", "higher"),
            TeamSpec("predator", (1,), "catches", "higher"),
        ),
    )
    monkeypatch.setattr(play, "make", lambda name, variant: FakeWorld(two_teams))

    results = play.final_evaluation(runs, tmp_path)

    assert [r.team for r in results] == ["prey", "predator"]
    opponents = Counter(
        (seed, kind) for seed, team, kind in played.episodes if team == "predator"
    )
    learned_or_baseline = {k for _, k in opponents}
    assert "rule" in learned_or_baseline
    prey_side = [
        (prey_kind, predator_kind)
        for (_, t1, prey_kind), (_, t2, predator_kind) in zip(
            played.episodes[::2], played.episodes[1::2], strict=True
        )
        if (t1, t2) == ("prey", "predator")
