SNAKE = TeamSpec("snake", (0,), "food eaten", "higher")


def collapse(points: list[list[float]], team: TeamSpec = SNAKE, random_mean: float = 1.0) -> Any:
    runs: Any = [EvalsOnly(eval_points(p)) for p in points]
    return summary.collapse_step(runs, team, random_mean)


